pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }

    function testFuzz_property(address logAddr) public {
        vm.assume(uint160(logAddr) != 0);
        vm.prank(address(0x1234));
        c.SetLogFile(logAddr);
        // General rule: configuring the log file never changes MinSum.
        assertTrue(c.MinSum() == 0);
    }
}
